.pr summary { display:flex; align-items:center; gap:14px; padding:14px 4px; cursor:pointer; list-style:none; font-family:var(--head); font-weight:700; font-size:16px; }
.pr summary::-webkit-details-marker { display:none; }
.pr summary img { width:28px; height:28px; }
.pr summary .m { font-weight:500; font-size:14px; color:var(--s400); }
.pr summary i { margin-left:auto; font-style:normal; font-family:var(--mono); font-weight:500; font-size:13px; color:var(--s400); }
.pr summary i:after { content:" позиций"; }
.pr[open] summary { background:color-mix(in srgb, var(--c) 18%, #fff); }
.pr .tw { padding-bottom:16px; }
.extra { margin-top:26px; font-size:14.5px; color:var(--s600); max-width:900px; }

/* условия и прочее */
.tl { display:grid; grid-template-columns:repeat(2,1fr); border-top:1.5px solid var(--ink); }
.tl div { display:grid; grid-template-columns:220px 1fr; gap:18px; padding:16px 0; border-bottom:1px solid var(--s100); }
.tl div:nth-child(odd) { padding-right:28px; }
.tl div:nth-child(even) { padding-left:28px; border-left:1px solid var(--s100); }
.tl dt { font-family:var(--head); font-weight:700; font-size:14px; }
.tl dd { font-size:14.5px; color:var(--s600); }
.extra-s { background:var(--yellow); }
.extra-s .kick, .extra-s .kick em { color:rgba(8,0,0,.55); }
.xl { list-style:none; display:grid; grid-template-columns:repeat(3,1fr); gap:14px; margin-top:20px; }
.xl li { background:#fff; border-radius:var(--r); padding:18px; display:flex; flex-direction:column; gap:10px; font-size:15px; }
.xl i { font-style:normal; font-size:12px; font-weight:600; align-self:flex-start; background:var(--ink); color:#fff; padding:2px 8px; border-radius:3px; }
.el { list-style:none; display:grid; grid-template-columns:repeat(auto-fill,minmax(250px,1fr)); gap:12px; }
.el li { background:#fff; border:1px solid var(--s100); border-radius:var(--r); padding:14px 16px; display:flex; flex-direction:column; gap:4px; }
.el b { font-family:var(--head); font-size:15px; }
.el span { font-size:13px; color:var(--s400); }
.note { margin-top:20px; font-size:15px; color:var(--s600); max-width:760px; }
.next { padding-top:0; }
.nl { list-style:none; display:grid; grid-template-columns:repeat(4,1fr); gap:18px; counter-reset:n; }
.nl li { border-top:4px solid var(--ink); padding-top:16px; display:flex; flex-direction:column; gap:8px; }
.nl li:nth-child(1) { border-color:var(--green); } .nl li:nth-child(2) { border-color:var(--cyan); } .nl li:nth-child(3) { border-color:var(--orange); } .nl li:nth-child(4) { border-color:var(--pink); }
.nl i { font-style:normal; font-size:13px; color:var(--s400); }
.nl b { font-family:var(--head); font-size:18px; line-height:1.2; }
.nl span { font-size:14.5px; color:var(--s600); }
.contacts { background:var(--ink); color:#fff; position:relative; }
.contacts:before { content:""; position:absolute; left:0; right:0; top:0; height:6px; background:var(--stripe); }
.contacts .kick { color:rgba(255,255,255,.6); }
.contacts .kick i { color:#fff; border-color:#fff; }
.ct { display:grid; grid-template-columns:1fr 1fr; gap:56px; }
.contacts h2 { margin-bottom:28px; }
.contacts .b { background:#fff; color:var(--ink); }
.contacts .b:hover { background:var(--yellow); }
.contacts .b.o { background:transparent; color:#fff; box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.6); }
.contacts .b.o:hover { background:#fff; color:var(--ink); }
.contacts dl { display:grid; grid-template-columns:150px 1fr; gap:12px 18px; font-size:15px; }
.contacts dt { color:rgba(255,255,255,.5); font-size:13px; padding-top:2px; }
.contacts dd a { color:#fff; }
.foot { margin-top:64px; font-size:12px; color:rgba(255,255,255,.4); }

@media (max-width:1100px) {
  .cg { grid-template-columns:repeat(3,1fr); }
  .fg { grid-template-columns:repeat(3,1fr); }
  .row { grid-template-columns:40px minmax(0,1fr) 150px 130px 22px; }
  .row .ob { display:none; }
  .facts { grid-template-columns:repeat(2,1fr); }
  .pos.off .row { grid-template-columns:40px minmax(0,1fr) 150px 130px 22px; }
}
@media (max-width:900px) {
  section { padding:72px 0; }
  .hg, .ct, .riv { grid-template-columns:1fr; }
  .riv .ph { min-height:0; aspect-ratio:16/9; }
  .stats { grid-template-columns:repeat(2,1fr); }
  .stats div:nth-child(3) { padding-left:0; border-left:0; }
  .lgd { grid-template-columns:repeat(2,1fr); }
  .tl { grid-template-columns:1fr; }
  .tl div:nth-child(n) { padding:14px 0; border-left:0; grid-template-columns:180px 1fr; }
  .xl { grid-template-columns:repeat(2,1fr); }
  .nl { grid-template-columns:repeat(2,1fr); }
  .facts { grid-template-columns:1fr; gap:14px; }
  .body { padding-left:4px; }
  .top nav { display:none; }
}
@media (max-width:640px) {
  .wrap { padding:0 16px; }
  section { padding:56px 0; }
  .hero { padding:44px 0 44px; }
  .cells { grid-template-columns:repeat(7,1fr); gap:5px; }
  .grid31 { padding:14px; }
  .stats { margin-top:36px; }
  .stats div, .stats div + div { padding:18px 10px 0 0; border-left:0; }
  .cg, .fg { grid-template-columns:repeat(2,1fr); gap:18px 12px; }
  .cc .s, .fc .s { font-size:12.5px; }
  .riv .tx { padding:22px 18px; }
  .riv b { font-size:21px; }
  .lgd { grid-template-columns:1fr; }
  .row { grid-template-columns:30px minmax(0,1fr) 22px; gap:6px 10px; padding:14px 2px; }
  .row .tg { grid-column:2; grid-row:2; font-size:12px; }
  .row .tg img { width:20px; height:20px; }
  .row .hd { grid-column:2; grid-row:3; text-align:left; font-size:14px; }
  .row .ar { grid-column:3; grid-row:1; }
  .row .nm { font-size:15px; }
  .pos.off .row { grid-template-columns:30px minmax(0,1fr); }
  .pos.off .tg { grid-column:2; grid-row:2; }
  details.pos > .row:before { left:-8px; }
  .th { grid-template-columns:1fr; padding:14px; }
  .th .tot { grid-row:auto; grid-column:1; justify-self:start; font-size:18px; }
  th, td { padding-left:14px; padding-right:14px; }
  table { min-width:560px; }
  .docs li { grid-template-columns:22px 1fr; }
  .docs li b { grid-column:2; }
  .tl div:nth-child(n) { grid-template-columns:1fr; gap:4px; }
  .xl, .nl { grid-template-columns:1fr; }
  .flt { top:60px; overflow-x:auto; flex-wrap:nowrap; }
  .flt button { white-space:nowrap; padding:8px 12px; font-size:13px; }
  .flt .ex { margin-left:0; }
  .contacts dl { grid-template-columns:1fr; gap:2px; }
  .contacts dd { margin-bottom:10px; }
  .ti .x { display:none; }
  .pr summary { font-size:14.5px; gap:10px; }
}
@media (max-height:500px) and (orientation:landscape) {
  .flt { position:static; }
  .top { position:static; }
}
@media (prefers-reduced-motion:reduce) { * { transition:none !important; scroll-behavior:auto !important; } }
@media print {
  .top, .flt, .btns { display:none; }
  details > *:not(summary) { display:block; }
}
.th .tot small { display:block; font-family:'Inter',sans-serif; font-size:12px; font-weight:500; color:var(--s600); margin-top:2px; }
.disc { margin-top:14px; max-width:820px; font-size:14.5px; color:var(--ink); background:#fff; border-left:4px solid var(--yellow); padding:12px 16px; border-radius:0 var(--r) var(--r) 0; }

</style>
